_GLSL_DECLARATION = re.compile(
    r"\b(?:void|float|double|int|uint|bool|[biud]?vec[234]|d?mat[234](?:x[234])?|"
    r"[iu]?sampler[A-Za-z0-9_]*|[iu]?image[A-Za-z0-9_]*)\s+([A-Za-z_]\w*)"
)

def _strip_glsl_comments(text):
    text=re.sub(r"/\*.*?\*/", " ", text, flags=re.S)
    return re.sub(r"//[^\n]*", " ", text)

def validate_glsl_reserved_identifiers(shaders):
    for rel,text in shaders.items():
        clean=_strip_glsl_comments(text)
        for match in _GLSL_DECLARATION.finditer(clean):
            name=match.group(1)
            if name in GLSL_RESERVED_IDENTIFIERS:
                line=clean.count("\n",0,match.start(1))+1
                fail(f"reserved GLSL identifier {name!r} in {rel}:{line}")
    print("26488 GLSL reserved-identifier lexical gate PASS")

def validate_photon_runtime_layout_parser(shaders):
    for rel,text in shaders.items():
        if text.count("#define LAYOUT //\nLAYOUT") != 1:
            fail(f"Photon LAYOUT header mismatch {rel}")
        runtime=text.replace(
            "#define LAYOUT //",
            "#define LAYOUT layout(local_size_x = 8, local_size_y = 8, local_size_z = 1) in;",
            1,
        )
        names=set();saw_local=False
        for no,line in enumerate(runtime.splitlines(),1):
            if "layout" not in line: continue
            if line.count("layout(") != 1: fail(f"Photon getLayouts multi-layout hazard {rel}:{no}: {line}")
            stripped=line.strip()
            if not (stripped.startswith("layout(") or stripped.startswith("#define LAYOUT layout(")):
                fail(f"Photon getLayouts prefix hazard {rel}:{no}: {line}")
            if stripped.startswith("layout(") and (stripped.count(";") != 1 or not stripped.endswith(";")):
                fail(f"Photon getLayouts trailing-token hazard {rel}:{no}: {line}")
            left=line.find("(");right=line.rfind(")")
            if left<0 or right<=left: fail(f"Photon getLayouts parentheses hazard {rel}:{no}")
            params=line[left+1:right].split(",")
            divided=line.replace("{","").split(" ")
            last=(divided[-1] if divided else "").replace(";","").replace("\n","")
            def parameter(name):
                for item in params:
                    pv=item.replace(" ","").split("=")
                    if pv and pv[0]==name:
                        if len(pv)!=2 or not re.fullmatch(r"-?\d+",pv[1]):
                            fail(f"Photon getLayouts non-integer {name} {rel}:{no}: {item}")
                        return int(pv[1])
                return 0
            if last=="in":
                if min(parameter("local_size_x"),parameter("local_size_y"),parameter("local_size_z"))<=0:
                    fail(f"Photon getLayouts invalid local size {rel}:{no}")
                saw_local=True
            else:
                if not re.fullmatch(r"[A-Za-z_]\w*",last): fail(f"Photon getLayouts resource-name hazard {rel}:{no}: {last!r}")
                if last in names: fail(f"Photon getLayouts duplicate resource {rel}:{no}: {last}")
                names.add(last);parameter("binding")
        if not saw_local: fail(f"Photon getLayouts lost compute layout {rel}")
    print("26488 exact Photon getLayouts runtime-parser simulation PASS")


GLES31_CORE_IMAGE_STORE_FORMATS = {
    "rgba32f", "rgba16f", "r32f", "rgba8", "rgba8_snorm",
    "rgba32ui", "rgba16ui", "rgba8ui", "r32ui",
    "rgba32i", "rgba16i", "rgba8i", "r32i",
}
_IMAGE_UNIFORM = re.compile(
    r"layout\s*\(([^)]*)\)\s*uniform\s+([^;]*\b(?:image|iimage|uimage)[A-Za-z0-9_]*\b[^;]*);"
)

def validate_gles_image_store_formats(shaders):
    for rel,text in shaders.items():
        clean=_strip_glsl_comments(text)
        for match in _IMAGE_UNIFORM.finditer(clean):
            layout_args=match.group(1)
            fmt=layout_args.split(",",1)[0].strip()
            if fmt not in GLES31_CORE_IMAGE_STORE_FORMATS:
                line=clean.count("\n",0,match.start())+1
                fail(f"non-core GLES 3.1 image load/store format {fmt!r} in {rel}:{line}")
    print("26488 GLES 3.1 image load/store format gate PASS")


def validate_generated_java_scope_contract(java):
    graph = java.find("IRIS_26487_RECONSTRUCTION_CORRECTNESS_BJZHOU_GRAPH")
    if graph < 0:
        fail("missing 26487 reconstruction graph marker for Java scope validation")
    graph_tail = java[graph:]
    if re.search(r"\bwronskiWb[RB]\b", graph_tail):
        fail("26488 V3 block-local wronskiWbR/B escaped into post-alignment graph")
    if graph_tail.count("wronskiGlobalWbR") < 2 or graph_tail.count("wronskiGlobalWbB") < 2:
        fail("26488 V3 method-scope WB authority missing from native MGC graph")
    owner = java.find("IRIS_26488_V3_DIAGNOSTIC_SCOPE_OWNER")
    if owner < 0:
        fail("26488 V3 diagnostic scope owner marker missing")
    diag_size = java.find("final Point iris26487DiagSize = new Point(48,36);", owner)
    diag_a = java.find("GLTexture iris26487DiagTexture = null;", owner)
    diag_b = java.find("GLTexture iris26488DenominatorDiagTexture = null;", owner)
    short_try = java.find("try{", owner)
    readback = java.find("IRIS_26488_COARSE_SUPPORT_AND_DENOMINATOR_TELEMETRY", owner)
    if min(diag_size, diag_a, diag_b, short_try, readback) < 0:
        fail("26488 V3 diagnostic scope contract incomplete")
    if not (owner < diag_size < short_try and owner < diag_a < short_try and owner < diag_b < short_try < readback):
        fail("26488 V3 diagnostic resources are not owned outside short-recovery try scope")
    if "GLTexture iris26487DiagTexture = new GLTexture(" in java or "GLTexture iris26488DenominatorDiagTexture = new GLTexture(" in java:
        fail("26488 V3 diagnostic resource was redeclared inside nested scope")
    if "if (iris26488DenominatorDiagTexture != null) iris26488DenominatorDiagTexture.close();" not in java:
        fail("26488 V3 denominator diagnostic null-safe close missing")
    if "if (iris26487DiagTexture != null) iris26487DiagTexture.close();" not in java:
        fail("26488 V3 support diagnostic null-safe close missing")
    print("26488 V3 generated-Java scope ownership gate PASS")

def numerical_self_test():
    rng=random.Random(26488)
    # Native RAW calibration must be algebraically identical to old RAW->CFA normalization for unsaturated sites.
    for _ in range(1000):
        black=rng.uniform(0,128); white=rng.uniform(512,16383); raw=rng.uniform(black,white)
        exposure=10**rng.uniform(-0.3,0.5); wb=10**rng.uniform(-0.2,0.5)
        old=((raw-black)/max(white-black,1.0))*exposure*wb
        native=max(raw-black,0.0)/max(white-black,1.0)*exposure*wb
        if abs(old-native)>1e-10: fail("native RAW calibration identity")
    # Camera2 affine noise transform: y=a*x -> S'=a*S, O'=a^2*O.
    for _ in range(300):
        S=10**rng.uniform(-6,-2);O=10**rng.uniform(-10,-4);x=rng.random();a=10**rng.uniform(-0.7,0.8);y=a*x
        if abs(a*a*(S*x+O)-((a*S)*y+a*a*O))>1e-10: fail("affine noise domain identity")
    # Current bjzhou RCD soft-highlight contract: below 0.985 is bit-exact unchanged; transition is bounded and calculation-domain only.
    threshold=0.985
    def clipmask(sensor):
        t=min(max((sensor-threshold)/(1.0-threshold),0.0),1.0)
        return t*t*(3.0-2.0*t)
    for v in (0.0,0.2,0.9,threshold-1e-8):
        if clipmask(v)!=0.0: fail("highlight repair touched unsaturated sample")
    if not (0.0 < clipmask((threshold+1.0)/2.0) < 1.0 and clipmask(1.0)==1.0): fail("highlight smoothstep contract")
    # Neutral color stays neutral after calculation WB accumulation and one final WB removal.
    for _ in range(300):
        camera=rng.uniform(0.01,0.9); wr=10**rng.uniform(-0.1,0.4); wb=10**rng.uniform(-0.1,0.4)
        calc=[camera*wr,camera,camera*wb]
        g=calc[1]; rg=calc[0]-g; bg=calc[2]-g
        out=[(g+rg)/wr,g,(g+bg)/wb]
        if max(abs(c-camera) for c in out)>1e-8: fail("neutral semantic/WB identity")
    # Camera2 lens shading in calculation RGB followed by WB removal is equivalent to camera-domain LSC.
    for _ in range(300):
        cam=[rng.random() for _ in range(3)]; wb=[rng.uniform(.8,3),1.0,rng.uniform(.8,3)]; lsc=[rng.uniform(1,3) for _ in range(3)]
        out=[cam[i]*wb[i]*lsc[i]/wb[i] for i in range(3)]
        exp=[cam[i]*lsc[i] for i in range(3)]
        if max(abs(out[i]-exp[i]) for i in range(3))>1e-8: fail("lens shading/WB ownership identity")
    # Whole-quad veto is forbidden: one clipped phase must not eliminate unrelated normal opponent samples.
    valid=[True,True,False,True]
    if sum(valid)!=3: fail("no-whole-quad-veto model")
    # Raw16ToGray: constant stays constant after equal-CFA averaging + separable 1:2:1 filtering.
    for _ in range(100):
        value=rng.uniform(0,32767)
        weights=[.25,.5,.25]
        filtered=sum(wx*wy*value for wy in weights for wx in weights)
        if abs(filtered-value)>1e-7: fail("Raw16ToGray constant identity")
    # Center impulse of grayAt contributes 0.25 through separable .5*.5 center weight.
    impulse=1000.0
    if abs(0.25*impulse-250.0)>1e-9: fail("Raw16ToGray impulse weight")
    if min(max(round(50000),0),32767)!=32767: fail("Raw16ToGray 32767 clamp")
    if abs((0.25*16383.0)/16383.0-0.25)>1e-12: fail("rejection /16383 luma scale")
    # Recovered rejection model-only smoke test. This is NOT claimed to predict phone support.
    weights=[]
    for _ in range(30000):
        excess=[max(rng.gauss(0.0,1.0)**2-1.0,0.0) for _ in range(3)]
        weights.append(2.0**(-0.07*sum(excess)/3.0))
    model_support=1.0+14.0*sum(weights)/len(weights)
    if model_support<14.0: fail("model-only static rejection support collapsed")
    print(f"26488 NUMERICAL SELF-TEST PASS modelOnly15FrameSupport={model_support:.6f} highlightThreshold={threshold:.3f}")

def validate_post(root):
    for rel,want in POST.items():
        p=root/rel
        if not p.is_file(): fail("missing post file "+rel)
        got=sha(p)
        if got!=want: fail(f"post hash {rel} got={got} want={want}")
    def read(rel): return (root/rel).read_text()
    recon=read("app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java")
    validate_generated_java_scope_contract(recon)
    direct=read("app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl")
    ref=read("app/src/main/assets/shaders/motionv2/mfsr_low_support_reference.glsl")
    guide=read("app/src/main/assets/shaders/motionv2/mfsr_bjzhou_guide.glsl")
    cov=read("app/src/main/assets/shaders/motionv2/mfsr_mgc_covariance.glsl")
    chroma=read("app/src/main/assets/shaders/motionv2/mfsr_chroma_guide.glsl")
    gray=read("app/src/main/assets/shaders/motionv2/mfsr_mgc_reference_gray.glsl")
    reduce4=read("app/src/main/assets/shaders/motionv2/mfsr_bjzhou_rejection_reduce4.glsl")
    final=read("app/src/main/assets/shaders/motionv2/mfsr_finalize.glsl")
    diag=read("app/src/main/assets/shaders/motionv2/mfsr_26488_stage_diag.glsl")
    required=[
        (direct,"IRIS_26488_BJZHOU_NATIVE_RAW_MERGERGB_NO_BLANKET_CENSOR"),
        (direct,"IRIS_26488_BJZHOU_HIGHLIGHT_CALCULATION_DOMAIN_CAMERA_FINALIZE_ONCE"),
        (ref,"IRIS_26488_REFERENCE_NATIVE_RAW_MERGERGB_IDENTITY_WEIGHT"),
        (guide,"IRIS_26488_BJZHOU_NATIVE_RAW_GUIDE_EXACT_STRUCTURE"),
        (cov,"IRIS_26488_BJZHOU_NATIVE_RAW_COVARIANCE_EXACT_GEOMETRY"),
        (chroma,"IRIS_26488_BJZHOU_NATIVE_RAW_EDGE_DIRECTED_CHROMA_GUIDE"),
        (gray,"IRIS_26488_BJZHOU_RAW16_TO_GRAY_HALIDE_CONTRACT"),
        (reduce4,"IRIS_26488_BJZHOU_REJECTION_DOWNSAMPLE_NATIVE_GRAY_EXACT"),
        (final,"IRIS_26488_BJZHOU_RGB_NORMALIZE_LSC_CAMERA_DOMAIN"),
        (diag,"IRIS_26488_SMALL_PER_FRAME_REJECTION_CONTRACT_ATLAS"),
        (recon,"IRIS_26488_RECON_DIAGNOSTICS"),
    ]
    for text,token in required:
        if token not in text: fail("missing semantic token "+token)
    for forbidden in ("sharedClipValidity","validSite","censoredOpponent"):
        if forbidden in direct or forbidden in ref: fail("blanket opponent censor survived: "+forbidden)
    if "uniform highp usampler2D rawTexture" not in direct or "sensorNormalizedAt" not in direct: fail("native R16UI MergeRgb missing")
    if "float opponent = highlightCalculationSampleAt(p) - localGreen" not in direct: fail("native opponent semantic missing")
    if "smoothstep(highlightClipThreshold, 1.0, sensor)" not in direct: fail("0.985 soft highlight reconstruction missing")
    if "calculationFallback" not in direct or "/ targetWb" in direct: fail("highlight domain ownership regressed")
    if "lensShadingMap" not in final or "0.5*(shading.g+shading.b)" not in final.replace(" ",""): fail("bjzhou lens shading normalize missing")
    if "referenceGray" not in reduce4 or "/ 16383.0" not in reduce4: fail("Raw16ToGray rejection producer mismatch")
    if "layout(r32ui,binding=0)" not in gray or "32767.0" not in gray: fail("GLES-safe exact reference-gray R32UI carrier missing")
    if "iris26488ReferenceGray = new GLTexture(rawHalf,new GLFormat(GLFormat.DataType.UNSIGNED_32,1)" not in recon: fail("Java reference-gray carrier is not R32UI/UNSIGNED_32")
    if "rawTexture" not in guide or "inputCfa" in guide: fail("MGC guide did not move to native RAW")
    if "rawTexture" not in cov or "inputCfa" in cov: fail("MGC covariance did not move to native RAW")
    if "rawTexture" not in chroma: fail("chroma guide did not move to native RAW")
    if "glProg.computeAutoDeferred" not in recon or "finishDeferredCompute(\"MotionV2 final image\")" not in recon: fail("26487 latency architecture missing")
    if recon.count("finishDeferredCompute(") != 1: fail("26488 introduced more than one Motion GPU completion drain")
    if "IRIS_26488_TINY_DIAGNOSTICS_BEFORE_SINGLE_GPU_DRAIN" not in recon: fail("tiny diagnostics are not queued before the single Motion drain")
    if "mfsr_26488_stage_diag" not in recon or "fullResolutionReadback=false" not in recon: fail("stage diagnostics contract missing")
    shaders={rel:read(rel) for rel in CHANGED_PATHS if rel.endswith('.glsl')}
    validate_glsl_reserved_identifiers(shaders)
    validate_photon_runtime_layout_parser(shaders)
    validate_gles_image_store_formats(shaders)
    numerical_self_test()
    print("26488 V3 FULL MERGERGB + REJECTION CONTRACT SOURCE VALIDATION PASS")

def main():
    if len(sys.argv)==2 and sys.argv[1]=='--self-test':
        decoded={rel:gzip.decompress(base64.b64decode(blob)).decode() for rel,blob in BLOBS.items()}
        embedded={rel:text for rel,text in decoded.items() if rel.endswith('.glsl')}
        validate_glsl_reserved_identifiers(embedded)
        validate_photon_runtime_layout_parser(embedded)
        validate_gles_image_store_formats(embedded)
        validate_generated_java_scope_contract(decoded["app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java"])
        numerical_self_test()
        return
    if len(sys.argv)!=2: fail("usage: transform_26488_full_merge_rgb_rejection_contract_v1.py <exact-26487-root> | --self-test")
    root=Path(sys.argv[1]).resolve()
    for rel,want in PRE.items():
        p=root/rel
        if want is None:
            if p.exists(): fail("new-file precondition violated "+rel)
        else:
            if not p.is_file(): fail("missing exact-26487 input "+rel)
            got=sha(p)
            if got!=want: fail(f"exact-26487 prehash mismatch {rel} got={got} want={want}")
    for rel,blob in BLOBS.items():
        p=root/rel; p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(gzip.decompress(base64.b64decode(blob)))
    validate_post(root)
    print("26488 V3 compile/scope-corrected MergeRgb rejection contract transform PASS")

if __name__=='__main__': main()
